package sohal.lld.snakeladder.entity.factory;import sohal.lld.snakeladder.entity.Entity;import sohal.lld.snakeladder.entity.Snake;import java.util.Set;import static sohal.lld.snakeladder.constants.Constants.RANDOM;public class SnakeFactory implements EntityFactory {    public Entity createEntity(Set<Integer> usedPositions) {        int head, tail;        while(true) {            head = RANDOM.nextInt(85) + 1;            int diff = RANDOM.nextInt(15) + 10;            tail = head - diff;            if(tail < 1) continue;            if(usedPositions.contains(tail) || usedPositions.contains(head)) continue;            break;        }        usedPositions.add(head);        usedPositions.add(tail);        return new Snake(head, tail);    }}